(424, '_elementor_onboarding_strings_en', 'a:2:{s:7:\"timeout\";i:1777523448;s:5:\"value\";s:4780:\"{\"common.continue\":\"Continue\",\"common.skip\":\"Skip\",\"common.back\":\"Back\",\"common.finish\":\"Finish\",\"common.loading\":\"Loading\\u2026\",\"common.upgrade\":\"Upgrade\",\"common.close_onboarding\":\"Close onboarding\",\"common.installed\":\"Installed\",\"common.recommended\":\"Recommended\",\"error.failed_mark_exit\":\"Failed to mark user exit.\",\"error.failed_complete_step\":\"Failed to complete step.\",\"error.pro_install_failed\":\"Couldn\'t install Elementor Pro. Please try again later\",\"error.theme_install_failed\":\"Theme installation didn\'t complete. Please try again later\",\"login.title\":\"Let\\u2019s get to work.\",\"login.sign_in\":\"Sign in to Elementor\",\"login.continue_another_way\":\"Continue another way\",\"login.continue_as_guest\":\"Continue as a guest\",\"steps.building_for.title\":\"Who are you building for?\",\"steps.building_for.greeting_with_name\":\"Hey %1$s %2$s Let\\u2019s get your site set up.\",\"steps.building_for.greeting_without_name\":\"Hey%s Let\\u2019s get your site set up.\",\"steps.building_for.option_myself\":\"Myself or someone I know\",\"steps.building_for.option_business\":\"My business or workplace\",\"steps.building_for.option_client\":\"A client\",\"steps.building_for.option_exploring\":\"Just exploring\",\"steps.site_about.title\":\"What is your site about?\",\"steps.site_about.subtitle\":\"Choose anything that applies.\",\"steps.site_about.option_small_med_business\":\"Small-Med Business\",\"steps.site_about.option_online_store\":\"Online store\",\"steps.site_about.option_company_site\":\"Company site\",\"steps.site_about.option_blog\":\"Blog\",\"steps.site_about.option_landing_page\":\"Landing page\",\"steps.site_about.option_booking\":\"Booking\",\"steps.site_about.option_organization\":\"Organization\",\"steps.site_about.option_other\":\"Other\",\"steps.site_about.greeting_myself\":\"Got it! We\\u2019ll keep things simple.\",\"steps.site_about.greeting_business\":\"Great! Let\\u2019s set up your business site.\",\"steps.site_about.greeting_client\":\"Nice! Let\\u2019s create something for your client.\",\"steps.site_about.greeting_fallback\":\"Let\\u2019s get started!\",\"steps.experience_level.title\":\"How experienced are you with Elementor?\",\"steps.experience_level.subtitle\":\"This helps us adjust the editor to your workflow.\",\"steps.experience_level.option_beginner\":\"I\\u2019m just getting started\",\"steps.experience_level.option_intermediate\":\"I have some experience\",\"steps.experience_level.option_advanced\":\"I\\u2019m very comfortable with Elementor\",\"steps.theme_selection.title\":\"Start with a theme that fits your needs\",\"steps.theme_selection.subtitle\":\"Hello themes are built to work seamlessly with Elementor.\",\"steps.theme_selection.aria_label\":\"Theme selection\",\"steps.theme_selection.theme_hello_label\":\"Hello\",\"steps.theme_selection.theme_hello_description\":\"A flexible canvas theme you can shape from the ground up\",\"steps.theme_selection.theme_hello_biz_label\":\"Hello Biz\",\"steps.theme_selection.theme_hello_biz_description\":\"A ready-to-start theme with smart layouts and widgets\",\"steps.theme_selection.greeting_beginner\":\"Glad you\\u2019re here!\",\"steps.theme_selection.greeting_default\":\"Great. Let\\u2019s take it to the next step\",\"steps.theme_selection.continue_with_theme\":\"Continue with this theme\",\"steps.site_features.title\":\"What do you want to include in your site?\",\"steps.site_features.subtitle\":\"We\\u2019ll use this to tailor suggestions for you.\",\"steps.site_features.continue_with_free\":\"Continue with Free\",\"steps.site_features.option_classes_variables\":\"Design system\",\"steps.site_features.option_interactions\":\"Interactions\",\"steps.site_features.option_theme_builder\":\"Theme builder\",\"steps.site_features.option_lead_collection\":\"Forms & leads\",\"steps.site_features.option_custom_code\":\"Custom Code\",\"steps.site_features.option_email_deliverability\":\"Email delivery\",\"steps.site_features.option_ai_generator\":\"AI tools\",\"steps.site_features.option_image_optimization\":\"Image optimization\",\"steps.site_features.option_accessibility_tools\":\"Accessibility\",\"steps.site_features.woocommerce\":\"WooCommerce\",\"steps.site_features.included\":\"Included\",\"steps.site_features.plan_recommendation_one\":\"Nice picks \\ud83d\\ude42 Elementor One has you covered.\",\"steps.site_features.plan_recommendation_pro\":\"Advanced tools? Elementor Pro includes them.\",\"steps.site_features.compare_plans\":\"View plans\",\"pro_install.title\":\"You already have a Pro subscription\",\"pro_install.subtitle\":\"Would you like to install it on this site now?\",\"pro_install.installing\":\"Installing Elementor Pro\\u2026\",\"pro_install.installing_short\":\"Installing\\u2026\",\"pro_install.install_button\":\"Install Pro on this site\",\"pro_install.logo_alt\":\"Elementor + Elementor Pro\",\"pro_install.do_it_later\":\"I\\u2019ll do it later\",\"completion.title\":\"Getting things ready\",\"completion.subtitle\":\"Tailoring the editor to your goals and workflow\\u2026\"}\";}', 'off'),
